64|const MAGIC: &[u8; 8] = b"SHKIVC06";
65|/// Name prefix of the node's own (self) fixed bases.
66|pub const SELF_NAME: &str = "shk_node";
67|/// State fields after the self key: prog_d, init_d, cur_d, h.
68|pub const IVC_STATE: usize = 4;
69|/// Leaf statement: prog_d, pre_d, post_d, rule, h_pre.
70|/// Leaf instance: [binding, prog_d, pre_d, post_d, rule, h_pre, steps]. The binding lane is
71|/// the leaf's own claim commitment (public input 0 of every ZKIR child); the node takes it as
72|/// a free witness and constrains the other lanes. `steps` (>= 1) is the number of machine
73|/// steps the leaf proves, so h counts machine steps: h = h_pre + steps.
74|pub const LEAF_LANES: usize = 7;
75|/// Most machine steps one leaf may prove (SRC-004; the G-A provisional S, task 2.3). A
76|/// relation constant: changing it changes the node key.
77|pub const S_MAX: u64 = 16;
78|/// Heights are integers below 2^H_BITS (SRC-004).
79|pub const H_BITS: usize = 64;
80|
81|/// Domain of a machine-state digest. Every leaf's pre_d/post_d is
82|/// `Poseidon(dom("SHK_SD"), outcome_tag, outcome_value, lanes_d)`, with
83|/// `lanes_d` the Poseidon digest of all carrier lanes, outcome_tag
84|/// `OUTCOME_RUNNING` (value 0) or `OUTCOME_HALTED` (value = the u128 result).
85|pub const DOM_STATE_D: &str = "SHK_SD";
86|pub const OUTCOME_RUNNING: u64 = 0;
87|pub const OUTCOME_HALTED: u64 = 1;
88|
89|/// (domain, halted tag) field constants of a halted state digest.
90|pub fn state_digest_halted() -> (F, F) {
91|    (crate::parent::dom(DOM_STATE_D), F::from(OUTCOME_HALTED))
92|}
93|
94|/// Off-circuit state digest.
95|pub fn state_digest(tag: u64, value: u128, lanes_d: F) -> F {
96|    crate::parent::poseidon(&[
97|        crate::parent::dom(DOM_STATE_D),
98|        F::from(tag),
99|        F::from_u128(value),
100|        lanes_d,
101|    ])
102|}
