104|/// The node relation. `self_k` fixes the node's own domain and constraint system.
105|#[derive(Clone, Debug)]
106|pub struct SherlockIvcRelation {
107|    pub nr_cols: u8,
108|    pub self_k: u32,
109|    pub leaf_vk: MidnightVK,
110|    self_domain: EvaluationDomain<F>,
111|    self_cs: ConstraintSystem<F>,
112|    /// MockProver negatives only: field values of (prev_h, steps) that replace the witness
113|    /// heights, which a `u64` cannot express (a height at or above 2^64). Witness values
114|    /// only; the constraint system and the key do not depend on it.
115|    raw_heights: Option<(F, F)>,
116|}
