133|pub struct IvcWitness {
134|    pub self_repr: F,
135|    pub prev: IvcState,
136|    /// Empty at genesis.
137|    pub prev_proof: Vec<u8>,
138|    pub prev_acc: Accumulator<S>,
139|    pub cur_d: F,
140|    pub rule: F,
141|    /// Public input 0 of the leaf proof (its claim binding), unconstrained by the node.
