148|/// The node's constraint system exactly as `MidnightCircuit` configures it.
149|pub fn node_cs(nr_cols: u8, k: u32) -> ConstraintSystem<F> {
150|    let mut cs = ConstraintSystem::default();
151|    let _ = ZkStdLib::configure(&mut cs, (bls_arch(nr_cols), (k - 1) as u8));
152|    cs
153|}
154|
155|impl SherlockIvcRelation {
156|    pub fn new(nr_cols: u8, self_k: u32, leaf_vk: MidnightVK) -> io::Result<Self> {
157|        if !(1..=4).contains(&nr_cols) || !(10..=24).contains(&self_k) {
158|            return Err(io::Error::other("node nr_cols in 1..=4 and k in 10..=24"));
159|        }
160|        let self_cs = node_cs(nr_cols, self_k);
161|        let self_domain = EvaluationDomain::new(self_cs.degree() as u32, self_k);
162|        Ok(Self {
163|            nr_cols,
164|            self_k,
165|            leaf_vk,
166|            self_domain,
167|            self_cs,
168|            raw_heights: None,
169|        })
170|    }
171|
172|    /// MockProver negatives only (see `raw_heights`): the circuit assigns these field values
173|    /// to `prev_h` and `steps` instead of the witness's `u64` heights.
174|    #[doc(hidden)]
175|    pub fn with_raw_heights(mut self, prev_h: F, steps: F) -> Self {
176|        self.raw_heights = Some((prev_h, steps));
177|        self
178|    }
179|
180|    pub fn leaf_name(&self) -> String {
181|        vk_name("shk_leaf", &self.leaf_vk)
182|    }
183|
184|    /// Fixed-base names of the self part of the carried accumulator.
185|    pub fn self_base_names(&self) -> Vec<String> {
186|        let selectors = vec![vec![false]; self.self_cs.num_selectors()];
187|        let (processed, _) = self
188|            .self_cs
189|            .clone()
190|            .directly_convert_selectors_to_fixed(selectors);
191|        fixed_base_names::<S>(
192|            SELF_NAME,
193|            processed.num_fixed_columns(),
194|            processed.permutation().columns.len(),
195|        )
196|    }
197|
198|    /// The genesis (trivial) accumulator: one default base, scalar one, and every
199|    /// self fixed-base scalar zero.
200|    pub fn trivial_acc(&self) -> Accumulator<S> {
201|        let zeros: BTreeMap<String, F> = self
202|            .self_base_names()
203|            .into_iter()
204|            .map(|n| (n, F::ZERO))
205|            .collect();
206|        Accumulator::new(
207|            Msm::new(&[C::default()], &[F::ONE], &BTreeMap::new()),
208|            Msm::new(&[C::default()], &[F::ONE], &zeros),
209|        )
210|    }
211|
212|    /// The public statement of a node proof.
213|    pub fn instance(self_repr: F, st: &IvcState, acc: &Accumulator<S>) -> Vec<F> {
214|        Self::instance_from_fields(self_repr, &st.fields(), acc)
215|    }
216|
217|    /// The public statement from raw state fields `[prog_d, init_d, cur_d, h]`.
218|    pub fn instance_from_fields(
219|        self_repr: F,
220|        fields: &[F; IVC_STATE],
221|        acc: &Accumulator<S>,
222|    ) -> Vec<F> {
223|        let mut v = vec![self_repr];
224|        v.extend(fields);
225|        v.extend(<AssignedAccumulator<S> as Instantiable<F>>::as_public_input(acc));
226|        v
227|    }
228|
229|    /// True iff `acc` has the public encoding of `trivial_acc`, the only carried
230|    /// accumulator a genesis node accepts (SRC-005 realization (a)).
231|    pub fn is_neutral(&self, acc: &Accumulator<S>) -> bool {
232|        <AssignedAccumulator<S> as Instantiable<F>>::as_public_input(acc)
233|            == <AssignedAccumulator<S> as Instantiable<F>>::as_public_input(&self.trivial_acc())
234|    }
235|
236|    /// Positions of the lhs and rhs variable-base scalars in the public encoding of a carried
237|    /// accumulator (one base per side, no lhs fixed-base scalars, every self fixed-base scalar
238|    /// on the rhs): `[P, 2P + 1]` with `P` the lanes of one point.
239|    pub fn carry_scalar_lanes(&self) -> [usize; 2] {
240|        let lanes =
241|            <AssignedAccumulator<S> as Instantiable<F>>::as_public_input(&self.trivial_acc());
242|        let pts = lanes.len() - 2 - self.self_base_names().len();
243|        assert!(
244|            pts % 2 == 0,
245|            "carried accumulator encoding: odd point lanes"
246|        );
247|        [pts / 2, pts + 1]
248|    }
249|
250|    /// True iff `acc` is in collapsed form: one base per side, each with scalar one, so that
251|    /// `collapse(acc) == acc` (the carried input of the Lean `nodeFold`, task 2.3).
252|    pub fn is_collapsed_carry(&self, acc: &Accumulator<S>) -> bool {
253|        let lanes = <AssignedAccumulator<S> as Instantiable<F>>::as_public_input(acc);
254|        let n =
255|            <AssignedAccumulator<S> as Instantiable<F>>::as_public_input(&self.trivial_acc()).len();
256|        lanes.len() == n
257|            && self
258|                .carry_scalar_lanes()
259|                .iter()
260|                .all(|&i| lanes[i] == F::ONE)
261|    }
262|
263|    pub fn leaf_instance(st_prev: &IvcState, binding: F, cur_d: F, rule: F, steps: u64) -> Vec<F> {
264|        vec![
265|            binding,
266|            st_prev.prog_d,
267|            st_prev.cur_d,
268|            cur_d,
269|            rule,
270|            F::from(st_prev.h),
271|            F::from(steps),
272|        ]
273|    }
274|
275|    /// Off-circuit: the accumulator node N_h exposes, given its witness and the
276|    /// real node key (None only at genesis, where the previous proof is absent).
277|    pub fn next_acc(
278|        &self,
279|        node_vk: Option<&MidnightVK>,
280|        w: &IvcWitness,
281|    ) -> Result<Accumulator<S>, String> {
282|        if w.prev.h == 0 && !self.is_neutral(&w.prev_acc) {
283|            return Err("genesis carried accumulator must be trivial_acc (SRC-005)".into());
284|        }
285|        if !self.is_collapsed_carry(&w.prev_acc) {
286|            return Err(
287|                "carried accumulator must be collapsed (one base, scalar one, per side)".into(),
288|            );
289|        }
290|        let leaf_inst = Self::leaf_instance(&w.prev, w.leaf_binding, w.cur_d, w.rule, w.leaf_steps);
291|        self.next_acc_raw(
292|            node_vk,
293|            w.self_repr,
294|            &w.prev.fields(),
295|            &w.prev_proof,
296|            &w.prev_acc,
297|            &leaf_inst,
298|            &w.leaf_proof,
299|        )
300|    }
301|
302|    /// `next_acc` over raw field values: the previous state fields `[prog_d, init_d, cur_d,
303|    /// h]` and the leaf instance. Genesis is `h == 0` in the field, exactly as in circuit.
304|    /// It checks nothing beyond the fold, so it also builds the statements of negative tests.
305|    #[allow(clippy::too_many_arguments)]
306|    pub fn next_acc_raw(
307|        &self,
308|        node_vk: Option<&MidnightVK>,
309|        self_repr: F,
310|        prev: &[F; IVC_STATE],
311|        prev_proof: &[u8],
312|        prev_acc: &Accumulator<S>,
313|        leaf_inst: &[F],
314|        leaf_proof: &[u8],
315|    ) -> Result<Accumulator<S>, String> {
316|        let genesis = prev[3] == F::ZERO;
317|        let proof_acc = if genesis {
318|            self.trivial_acc()
319|        } else {
320|            let vk = node_vk.ok_or("non-genesis step needs the node key")?;
321|            let prev_inst = Self::instance_from_fields(self_repr, prev, prev_acc);
322|            let mut tr = CircuitTranscript::<PoseidonState<F>>::init_from_bytes(prev_proof);
323|            let dual = plonk::prepare::<
324|                F,
325|                KZGCommitmentScheme<Bls12>,
326|                CircuitTranscript<PoseidonState<F>>,
327|            >(vk.vk(), &[&[C::identity()]], &[&[&prev_inst]], &mut tr)
328|            .map_err(|e| format!("prepare previous node proof: {e:?}"))?;
329|            let bases = fixed_bases::<S>(SELF_NAME, vk.vk());
330|            // Collapsed, mirroring the circuit: the fold challenge hashes every folded
331|            // accumulator, so the genesis one must be the canonical trivial accumulator.
332|            let mut a = Accumulator::<S>::from_dual_msm(dual, SELF_NAME, &bases);
333|            a.collapse();
334|            a
335|        };
336|        let leaf_acc = prepare_offcircuit_with(
337|            &self.leaf_vk,
338|            &self.leaf_name(),
339|            leaf_inst,
340|            leaf_proof,
341|            false,
342|            false,
343|        )?;
344|        let mut acc = Accumulator::accumulate(&[proof_acc, prev_acc.clone(), leaf_acc]);
345|        acc.collapse();
346|        Ok(acc)
347|    }
348|
349|    /// Off-circuit final check of a node accumulator against the real node key.
350|    pub fn check_acc(
351|        params: &ParamsVerifierKZG<Bls12>,
352|        node_vk: &MidnightVK,
353|        acc: &Accumulator<S>,
354|    ) -> bool {
355|        acc.check(params, &fixed_bases::<S>(SELF_NAME, node_vk.vk()))
356|    }
357|}
358|
359|/// SRC-004 height checks; returns `h = prev_h + steps`. Heights are integers below 2^64,
360|/// `1 <= steps <= S_MAX` (as `steps - 1` in `[0, S_MAX)`, one check for both bounds), and the
361|/// sum is checked again, so `h` is the integer `prev_h + steps < 2^64`, `h >= 1`, and `h`
362|/// cannot wrap to 0 (which would set `is_genesis` on a later step and drop the previous proof).
363|pub fn constrain_heights(
364|    std: &ZkStdLib,
365|    l: &mut impl Layouter<F>,
366|    prev_h: &AssignedNative<F>,
367|    steps: &AssignedNative<F>,
368|) -> Result<AssignedNative<F>, Error> {
369|    let h_bound = BigUint::from(1u8) << H_BITS;
370|    std.assert_lower_than_fixed(l, prev_h, &h_bound)?;
371|    let steps_m1 = std.add_constant(l, steps, -F::ONE)?;
372|    std.assert_lower_than_fixed(l, &steps_m1, &BigUint::from(S_MAX))?;
373|    let h = std.add(l, prev_h, steps)?;
374|    std.assert_lower_than_fixed(l, &h, &h_bound)?;
375|    Ok(h)
376|}
377|
378|/// SRC-005 realization (a): at genesis no previous proof authenticates the carried
379|/// accumulator (its proof is scaled away), so its public encoding `lanes` must equal the
380|/// neutral encoding of `trivial_acc`: `is_genesis * (lane - neutral) == 0` for every lane.
381|/// `accumulate` hashes exactly these lanes, so at genesis the fold challenge and the folded
382|/// value depend on the leaf alone: no grinding and no cancellation through the carry.
383|pub fn constrain_genesis_neutral(
384|    std: &ZkStdLib,
385|    l: &mut impl Layouter<F>,
386|    is_genesis: &AssignedBit<F>,
387|    lanes: &[AssignedNative<F>],
388|    neutral: &[F],
389|) -> Result<(), Error> {
390|    if neutral.len() != lanes.len() {
391|        return Err(Error::Synthesis(
392|            "carried accumulator encoding length differs from trivial_acc".into(),
393|        ));
394|    }
395|    let g: AssignedNative<F> = is_genesis.clone().into();
396|    for (x, t) in lanes.iter().zip(neutral) {
397|        let d = std.add_and_mul(l, (F::ZERO, x), (-*t, &g), (F::ZERO, x), F::ZERO, F::ONE)?;
398|        std.assert_zero(l, &d)?;
399|    }
400|    Ok(())
401|}
402|
403|/// The carried accumulator is in collapsed form at every height: the variable-base scalar of
404|/// each side (lanes `idx` of its public encoding) equals one, so `collapse(carry) == carry` and
405|/// the node fold equals the Lean `nodeFold b p c l = collapse (accumulate [collapse (scale b p),
406|/// collapse (scale b c), l])` without a second in-circuit MSM. Off genesis the previous node
407|/// published exactly such an accumulator (`next.collapse()`); this makes it a local constraint
408|/// rather than a consequence of the deferred previous proof.
409|pub fn constrain_collapsed_carry(
410|    std: &ZkStdLib,
411|    l: &mut impl Layouter<F>,
412|    lanes: &[AssignedNative<F>],
413|    idx: [usize; 2],
414|) -> Result<(), Error> {
415|    for i in idx {
416|        let x = lanes.get(i).ok_or_else(|| {
417|            Error::Synthesis("carried accumulator scalar lane out of range".into())
418|        })?;
419|        std.assert_equal_to_fixed(l, x, F::ONE)?;
420|    }
421|    Ok(())
422|}
423|
424|/// Inverse of the public accumulator encoding of a node instance tail, given the
425|/// self fixed-base names; refuses any lanes that do not re-encode identically.
426|pub fn acc_from_lanes(lanes: &[F], names: &[String]) -> Option<Accumulator<S>> {
427|    let np = crate::inner::point_pi_len();
428|    if lanes.len() != 2 * (np + 1) + names.len() {
429|        return None;
430|    }
431|    let pt = |s: &[F]| <crate::inner::AP as Instantiable<F>>::from_public_input(s);
432|    let (lb, ls) = (pt(&lanes[..np])?, lanes[np]);
433|    let (rb, rs) = (pt(&lanes[np + 1..2 * np + 1])?, lanes[2 * np + 1]);
434|    let mut sorted = names.to_vec();
435|    sorted.sort();
436|    let fixed: BTreeMap<String, F> = sorted
437|        .into_iter()
438|        .zip(lanes[2 * np + 2..].iter().copied())
439|        .collect();
440|    let acc = Accumulator::new(
441|        Msm::new(&[lb], &[ls], &BTreeMap::new()),
442|        Msm::new(&[rb], &[rs], &fixed),
443|    );
444|    (<AssignedAccumulator<S> as Instantiable<F>>::as_public_input(&acc) == lanes).then_some(acc)
445|}
