240|fn prepare(
241|    source: &str,
242|    action: &str,
243|    scenario: &Scenario,
244|    target: &Target,
245|    options: &ProofOptions,
246|    mode: Mode,
247|) -> Result<Prepared, Error> {
248|    if options.max_k == 0 || options.max_k > MAX_K {
249|        return Err(error("limit", "Native k cap must be between 1 and 19."));
250|    }
251|    let (statement, private) = match mode {
252|        Mode::Unsigned => (
253|            signed_relation::reconstruct(source, action, scenario, target, None)?,
254|            Vec::new(),
255|        ),
256|        Mode::Verify((authority, at, intent)) => (
257|            signed_relation::accept(source, action, scenario, target, authority, at, intent)?,
258|            Vec::new(),
259|        ),
260|        Mode::Prove((authority, at, intent)) => {
261|            let statement =
262|                signed_relation::accept(source, action, scenario, target, authority, at, intent)?;
263|            let witness = signed_relation::witness(&statement, intent)?;
264|            (statement, witness)
265|        }
266|    };
267|    let circuit = &statement.circuit;
268|    let values = statement.public_values();
269|    let ir = IrSource::load(circuit.zkir.as_bytes()).map_err(|e| error("zkir", e.to_string()))?;
270|    if ir.do_communications_commitment || !ir.inputs.is_empty() {
271|        return Err(error(
272|            "unsupported",
273|            "Only the current public, communications-disabled ABI is supported.",
274|        ));
275|    }
276|    let k = ir.k();
277|    if k == 0 || k > options.max_k || k > MAX_K {
278|        return Err(error(
279|            "limit",
280|            format!(
281|                "Compiled circuit k={k} exceeds the explicit native k cap {}.",
282|                options.max_k
283|            ),
284|        ));
285|    }
286|    // The pinned embedded verifier SRS has degree 14. Circuit degree may be
287|    // larger, but its public statement must fit that verifier's input capacity.
288|    if values.len() + 1 > (1usize << VERIFIER_MAX_DEGREE) {
289|        return Err(error(
290|            "limit",
291|            "Public statement exceeds the pinned verifier capacity.",
292|        ));
293|    }
294|    let claim = claim_from_reconstruction(&statement, action, scenario, target, k)?;
295|    // SHA-256 is interpreted little-endian as low128 + 2^128 * high128,
296|    // reduced modulo the pinned Fr by field arithmetic. This is not truncation.
297|    // binding_input binds this host-reconstructed claim; it does not prove an
298|    // in-circuit hash of the entire local report.
299|    let hash = digest(&(BINDING_VERSION, &claim))?;
300|    let low = u128::from_le_bytes(
301|        hash[..16]
302|            .try_into()
303|            .map_err(|_| error("serialization", "Invalid digest limb."))?,
304|    );
305|    let high = u128::from_le_bytes(
306|        hash[16..]
307|            .try_into()
308|            .map_err(|_| error("serialization", "Invalid digest limb."))?,
309|    );
310|    let binding = Fr::from(low) + (Fr::from(u128::MAX) + Fr::from(1u64)) * Fr::from(high);
311|    // The exported report must itself remain admissible to the public bounded
312|    // JSON reader; validate it before native key generation or proving.
313|    // Reserve the largest admitted decimal proof count in the actual escaped
314|    // receipt so a size refusal cannot first appear after expensive proving.
315|    let report = receipt(
316|        &claim.authorization_mode,
317|        statement.execution.clone(),
318|        k,
319|        MAX_PROOF_BYTES as u32,
320|    );
321|    validate_json_profile(&report)?;
322|    validate_json_profile(&with_proof(&claim, &"00".repeat(MAX_PROOF_BYTES))?)?;
323|    Ok(Prepared {
324|        claim,
325|        execution: statement.execution,
326|        ir,
327|        values,
328|        private,
329|        binding,
330|    })
