190|    fn circuit(
191|        &self,
192|        std: &ZkStdLib,
193|        l: &mut impl Layouter<F>,
194|        instance: Value<Vec<F>>,
195|        witness: Value<RunDeciderWitness>,
196|    ) -> Result<(), Error> {
197|        let verifier = std.verifier();
198|        let ecc = std.bls12_381();
199|        let n = self.n_w_instance();
200|
201|        // 1. Node instance, own key pinned.
202|        let mut w_inst: Vec<AssignedNative<F>> = Vec::with_capacity(n);
203|        for i in 0..n {
204|            w_inst.push(std.assign(l, witness.as_ref().map(|w| w.w_instance[i]))?);
205|        }
206|        std.assert_equal_to_fixed(l, &w_inst[0], self.node_vk.vk().transcript_repr())?;
207|
208|        // 2. Verify the node proof, fold its carried accumulator, resolve, collapse.
209|        let pvk = self.node_vk.vk();
210|        let assigned_vk = verifier.assign_fixed_vk(
211|            l,
212|            SELF_NAME,
213|            pvk.get_domain(),
214|            pvk.cs(),
215|            pvk.transcript_repr(),
216|        )?;
217|        let mut bases = BTreeMap::new();
218|        for (name, base) in fixed_bases::<S>(SELF_NAME, pvk) {
219|            bases.insert(name, ecc.assign_fixed(l, base)?);
220|        }
221|        let committed = [ecc.assign_fixed(l, C::identity())?];
222|        let own = verifier.prepare(
223|            l,
224|            &assigned_vk,
225|            &committed,
226|            &[w_inst.as_slice()],
227|            witness.as_ref().map(|w| w.w_proof.clone()),
228|        )?;
229|        let carried = verifier.assign_collapsed_accumulator(
230|            l,
231|            &self.node_base_names(),
232|            witness.as_ref().map(|w| w.w_acc.clone()),
233|        )?;
234|        let enc = verifier.as_public_input(l, &carried)?;
235|        if enc.len() != n - 1 - IVC_STATE {
236|            return Err(Error::Synthesis(
237|                "carried accumulator encoding length".into(),
238|            ));
239|        }
240|        for (a, b) in w_inst[1 + IVC_STATE..].iter().zip(enc.iter()) {
241|            std.assert_equal(l, a, b)?;
242|        }
243|        let mut acc = verifier.accumulate(l, &[own, carried])?;
244|        acc.resolve_fixed_bases(&bases);
245|        acc.collapse(l, ecc, ecc.scalar_field_chip())?;
246|
247|        // 3. Pairing of the collapsed points (as in decider.rs).
248|        let enc = verifier.as_public_input(l, &acc)?;
249|        let np = point_pi_len();
250|        if enc.len() != 2 * (np + 1) {
251|            return Err(Error::Synthesis(
252|                "unexpected accumulator encoding length".into(),
253|            ));
254|        }
255|        let accv = acc.value();
256|        let a_val = accv.as_ref().map(|a| a.lhs().bases()[0]);
257|        let b_val = accv.as_ref().map(|a| a.rhs().bases()[0]);
258|        let a: AG1 =
259|            AssignmentInstructions::<F, AG1>::assign(ecc, l, a_val.map(G1Projective::from))?;
260|        let b: AG1 =
261|            AssignmentInstructions::<F, AG1>::assign(ecc, l, b_val.map(G1Projective::from))?;
262|        let ea = ecc.as_public_input(l, &a)?;
263|        let eb = ecc.as_public_input(l, &b)?;
264|        for (x, y) in ea.iter().zip(&enc[..np]) {
265|            std.assert_equal(l, x, y)?;
266|        }
267|        for (x, y) in eb.iter().zip(&enc[np + 1..2 * np + 1]) {
268|            std.assert_equal(l, x, y)?;
269|        }
270|        std.assert_equal_to_fixed(l, &enc[np], F::ONE)?;
271|        std.assert_equal_to_fixed(l, &enc[2 * np + 1], F::ONE)?;
272|        let g = PairingGadget::new(Tower::new(ecc.base_field_chip(), TowerOpts::default()));
273|        let (lt, ln) = kzg_decider_lines(&self.s_g2);
274|        let pa = g.prepare_assigned_g1(l, ecc, &a)?;
275|        let pb = g.prepare_assigned_g1(l, ecc, &b)?;
276|        g.assert_pairing_product_is_one(l, &[(pa, lt), (pb, ln)])?;
277|
278|        // 4. The final state is halted with a u128 result.
279|        let result: AssignedNative<F> =
280|            std.assign(l, witness.as_ref().map(|w| F::from_u128(w.result)))?;
281|        // 16 bytes: range check result < 2^128 and its big-endian field form.
282|        let le = std.assigned_to_le_bytes(l, &result, Some(16))?;
283|        let result_be: AssignedNative<F> = std.assigned_from_be_bytes(l, &le)?;
284|        let lanes_d: AssignedNative<F> = std.assign(l, witness.as_ref().map(|w| w.lanes_d))?;
285|        let sd_dom: AssignedNative<F> = std.assign_fixed(l, state_digest_halted().0)?;
286|        let halted: AssignedNative<F> = std.assign_fixed(l, state_digest_halted().1)?;
287|        let fin = std.poseidon(l, &[sd_dom, halted, result.clone(), lanes_d])?;
288|        std.assert_equal(l, &fin, &w_inst[3])?;
289|
290|        // 5. Public values, stmt and the bound communication commitment.
291|        let values = [
292|            w_inst[1].clone(),
293|            w_inst[2].clone(),
294|            w_inst[3].clone(),
295|            w_inst[4].clone(),
296|            result_be,
297|        ];
298|        let d: AssignedNative<F> = std.assign_fixed(l, dom(DOM_RUN))?;
299|        let mut pre = vec![d];
300|        pre.extend(values.iter().cloned());
301|        let stmt = std.poseidon(l, &pre)?;
302|        let rand: AssignedNative<F> = std.assign(l, witness.as_ref().map(|w| w.comm_rand))?;
303|        let mut cpre = vec![rand];
304|        for &i in &self.cc_inputs {
305|            cpre.push(if i == CC_STMT {
306|                stmt.clone()
307|            } else {
308|                values[i as usize].clone()
309|            });
310|        }
311|        let cc = std.poseidon(l, &cpre)?;
312|
313|        // 6. Public inputs in template order.
314|        for (idx, slot) in self.template.slots.iter().enumerate() {
315|            let x: AssignedNative<F> = match slot {
316|                Slot::BindingInput => std.assign(l, instance.as_ref().map(|v| v[idx]))?,
317|                Slot::CommunicationCommitment => {
318|                    let x: AssignedNative<F> = std.assign(l, instance.as_ref().map(|v| v[idx]))?;
319|                    std.assert_equal(l, &x, &cc)?;
320|                    x
321|                }
322|                Slot::Const(c) => std.assign_fixed(l, *c)?,
323|                Slot::Stmt => stmt.clone(),
324|                Slot::Value(i) => values[*i as usize].clone(),
325|            };
326|            std.constrain_as_public_input(l, &x)?;
327|        }
328|        Ok(())
329|    }
330|
331|    fn used_chips(&self) -> ZkStdLibArch {
332|        bls_arch(self.nr_cols)
333|    }
334|
335|    fn write_relation<W: io::Write>(&self, w: &mut W) -> io::Result<()> {
336|        w.write_all(MAGIC)?;
337|        w.write_all(&[self.nr_cols])?;
338|        write_bytes(w, &vk_bytes(&self.node_vk))?;
339|        w.write_all(self.s_g2.to_bytes().as_ref())?;
340|        w.write_all(&(self.cc_inputs.len() as u32).to_le_bytes())?;
341|        for i in &self.cc_inputs {
342|            w.write_all(&i.to_le_bytes())?;
343|        }
344|        write_f(w, &dom(DOM_RUN))?;
345|        self.template.write(w)
346|    }
347|
348|    fn read_relation<R: io::Read>(r: &mut R) -> io::Result<Self> {
349|        let mut magic = [0u8; 8];
350|        r.read_exact(&mut magic)?;
351|        if &magic != MAGIC {
352|            return Err(io::Error::other("not a SHKRUND1 run decider relation"));
353|        }
354|        let mut b = [0u8; 1];
355|        r.read_exact(&mut b)?;
356|        let node_vk = vk_from_bytes(&read_bytes(r, 1 << 20)?)?;
357|        let mut enc = <G2Affine as GroupEncoding>::Repr::default();
358|        r.read_exact(enc.as_mut())?;
359|        let s_g2: G2Affine = Option::from(G2Affine::from_bytes(&enc))
360|            .ok_or_else(|| io::Error::other("s_g2 not a valid G2 point"))?;
361|        let n = read_u32(r)? as usize;
362|        if n > 16 {
363|            return Err(io::Error::other("too many cc inputs"));
364|        }
365|        let mut cc_inputs = Vec::with_capacity(n);
366|        for _ in 0..n {
367|            cc_inputs.push(read_u32(r)?);
368|        }
369|        if read_f(r)? != dom(DOM_RUN) {
370|            return Err(io::Error::other("run decider domain differs"));
371|        }
372|        let template = Template::read(r)?;
373|        let rel = Self {
374|            nr_cols: b[0],
375|            node_vk,
376|            s_g2,
377|            template,
378|            cc_inputs,
379|        };
380|        rel.validate()?;
381|        Ok(rel)
382|    }
