93|            + <midnight_circuits::verifier::AssignedAccumulator<S> as midnight_circuits::types::Instantiable<F>>::as_public_input(
94|                &self.trivial_carried(),
95|            )
96|            .len()
97|    }
98|
99|    fn trivial_carried(&self) -> Accumulator<S> {
100|        use midnight_circuits::verifier::Msm;
101|        let zeros: BTreeMap<String, F> = self
102|            .node_base_names()
103|            .into_iter()
104|            .map(|n| (n, F::ZERO))
105|            .collect();
106|        Accumulator::new(
107|            Msm::new(&[C::default()], &[F::ONE], &BTreeMap::new()),
108|            Msm::new(&[C::default()], &[F::ONE], &zeros),
109|        )
110|    }
111|
112|    pub fn validate(&self) -> io::Result<()> {
113|        if !(1..=4).contains(&self.nr_cols) {
114|            return Err(io::Error::other("nr_cols must be in 1..=4"));
115|        }
116|        if bool::from(self.s_g2.is_identity()) {
117|            return Err(io::Error::other("s_g2 is the identity"));
118|        }
119|        self.template.validate()?;
120|        for s in &self.template.slots {
121|            if let Slot::Value(i) = s
122|                && *i as usize >= N_VALUES
123|            {
124|                return Err(io::Error::other("value slot index out of range"));
125|            }
126|        }
127|        if self
128|            .cc_inputs
129|            .iter()
130|            .any(|&i| i != CC_STMT && i as usize >= N_VALUES)
131|        {
132|            return Err(io::Error::other("cc input index out of range"));
133|        }
134|        Ok(())
135|    }
136|
137|    /// The public values for a node instance and its halted result.
138|    pub fn values(w_instance: &[F], result: u128) -> [F; N_VALUES] {
139|        [
140|            w_instance[1],
141|            w_instance[2],
142|            w_instance[3],
143|            w_instance[4],
144|            F::from_u128(result_be(result)),
145|        ]
146|    }
147|
148|    pub fn stmt(values: &[F; N_VALUES]) -> F {
149|        let mut pre = vec![dom(DOM_RUN)];
150|        pre.extend_from_slice(values);
151|        poseidon(&pre)
152|    }
153|
154|    pub fn comm(&self, stmt: F, values: &[F; N_VALUES], comm_rand: F) -> F {
155|        let mut pre = vec![comm_rand];
156|        for &i in &self.cc_inputs {
157|            pre.push(if i == CC_STMT {
158|                stmt
159|            } else {
160|                values[i as usize]
161|            });
162|        }
163|        poseidon(&pre)
164|    }
165|
166|    /// The ledger public-input vector of the call.
167|    pub fn public_inputs(&self, binding_input: F, w: &RunDeciderWitness) -> Option<Vec<F>> {
168|        let v = Self::values(&w.w_instance, w.result);
169|        let stmt = Self::stmt(&v);
170|        let cc = self.comm(stmt, &v, w.comm_rand);
171|        self.template
172|            .public_inputs_with(binding_input, cc, stmt, &v)
173|    }
174|}
175|
176|/// The u128 whose little-endian bytes are the big-endian bytes of `r`.
177|pub fn result_be(r: u128) -> u128 {
178|    u128::from_le_bytes(r.to_be_bytes())
179|}
