    pub fn new(program: Arc<Program>, fuel: u128, stack_limit: usize) -> Self {
        Self {
            state: Snapshot {
                control: Some(Control::Eval(program.entry.clone())),
                program,
                environment: Environment::new(),
                frames: vec![],
                stack_limit,
                remaining_fuel: fuel,
                initial_fuel: fuel,
                outcome: Outcome::Pending,
            },
        }
    }

    pub fn snapshot(&self) -> Snapshot {
        self.state.clone()
    }

    /// Resume a technical cut from its complete [`Snapshot`]. The snapshot is the
    /// whole `sherlock-k-a/1` state, so no field is defaulted or inferred.
    pub fn from_snapshot(state: Snapshot) -> Self {
        Self { state }
    }

